import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse(`{"title":"js Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"js","tag":"js","title":"js Tag","prev":null,"next":"/tags/js/page/2/","posts":[{"title":"TypeScript中应该禁止使用enum","url":"/posts/2022-07-04-typescript-enum/","date":"2022-07-04 20:37","tags":["js"],"html":"<p>TypeScript 添加了一个 <code>enum</code> 的数据类型结构，但是这个数据类型在 JavaScript 中并不存在，在编译过程中会被转换成 Object。并且 enum 类型可以完全被 union 类型替代。\\n所以我们推荐使用 union 来代替 enum。接下来我们使用一个例子来解释下 enum 如何被替换成 union。</p>\\n<h2 id=\\"enum-定义数据类型\\" tabindex=\\"-1\\">enum 定义数据类型 <a class=\\"header-anchor\\" href=\\"#enum-定义数据类型\\" aria-label=\\"Permalink to &quot;enum 定义数据类型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们来封装一个常见的 fetch 函数，使用 enum 定义的代码如下。</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">enum</span><span style=\\"color:#6F42C1\\"> HTTPRequestMethod</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  GET</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'GET'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  POST</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'POST'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> fetchJSON</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">url</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">method</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> HTTPRequestMethod</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> fetch</span><span style=\\"color:#24292E\\">(url, { method }).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">response</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> response.</span><span style=\\"color:#6F42C1\\">json</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>编译成 JS 代码如下：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#032F62\\">'use strict'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> HTTPRequestMethod;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">HTTPRequestMethod</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  HTTPRequestMethod[</span><span style=\\"color:#032F62\\">'GET'</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'GET'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  HTTPRequestMethod[</span><span style=\\"color:#032F62\\">'POST'</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'POST'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">})(HTTPRequestMethod </span><span style=\\"color:#D73A49\\">||</span><span style=\\"color:#24292E\\"> (HTTPRequestMethod </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {}));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> fetchJSON</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">url</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">method</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> fetch</span><span style=\\"color:#24292E\\">(url, { method }).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">response</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> response.</span><span style=\\"color:#6F42C1\\">json</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>这样编译的 JS 代码，定义了 HTTPRequestMethod 对象，但并不是 const 常量，有被更改的可能性，非常不优雅。</p>\\n<h2 id=\\"union-定义数据类型\\" tabindex=\\"-1\\">union 定义数据类型 <a class=\\"header-anchor\\" href=\\"#union-定义数据类型\\" aria-label=\\"Permalink to &quot;union 定义数据类型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> HTTPRequestMethod</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  GET: </span><span style=\\"color:#032F62\\">'GET'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  POST: </span><span style=\\"color:#032F62\\">'POST'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">} </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">type</span><span style=\\"color:#6F42C1\\"> ValuesOf</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">T</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">[</span><span style=\\"color:#D73A49\\">keyof</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">type</span><span style=\\"color:#6F42C1\\"> HTTPRequestMethodType</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> ValuesOf</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#24292E\\"> HTTPRequestMethod>;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> fetchJSON</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">url</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">method</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> HTTPRequestMethodType</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> fetch</span><span style=\\"color:#24292E\\">(url, { method }).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">response</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> response.</span><span style=\\"color:#6F42C1\\">json</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>编译成 js 代码之后是：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#032F62\\">'use strict'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> HTTPRequestMethod</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  GET: </span><span style=\\"color:#032F62\\">'GET'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  POST: </span><span style=\\"color:#032F62\\">'POST'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> fetchJSON</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">url</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">method</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> fetch</span><span style=\\"color:#24292E\\">(url, { method }).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">response</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> response.</span><span style=\\"color:#6F42C1\\">json</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>对比 enum 和 union 定义生成的代码，我们能明显感受到 union 类型生成的代码更优雅。而且 enum 还有其他缺点，大家可以查看下参考链接。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.kabuku.co.jp/developers/good-bye-typescript-enum\\" target=\\"_blank\\" rel=\\"noreferrer\\">さようなら、TypeScript enum</a></p>\\n<p><a href=\\"https://stackoverflow.com/a/60041791\\" target=\\"_blank\\" rel=\\"noreferrer\\">Why it is not good to use enums?</a></p>\\n<p><a href=\\"https://mariusschulz.com/blog/const-assertions-in-literal-expressions-in-typescript\\" target=\\"_blank\\" rel=\\"noreferrer\\">Const Assertions in Literal Expressions in TypeScript</a></p>\\n"},{"title":"JS中关于深拷贝和浅拷贝","url":"/posts/2022-06-20-deep-copy/","date":"2022-06-20 19:37","tags":["js"],"html":"<p>JS 有基本数据类型和复合数据类型，基本数据类型包括 null，undefined，boolean，number，string，symbol。针对这些数据类型都是值拷贝。复合数据类型包括 object，以及衍生的内置数据类型，Array, Map, Set 等等。默认对复合数据类型的赋值操作都是引用拷贝，就是浅拷贝。</p>\\n<h2 id=\\"json-stringify-实现深拷贝\\" tabindex=\\"-1\\">JSON.stringify 实现深拷贝 <a class=\\"header-anchor\\" href=\\"#json-stringify-实现深拷贝\\" aria-label=\\"Permalink to &quot;JSON.stringify 实现深拷贝&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>一种常用的方式是使用 JSON 接口先转换成字符串再解析成对象。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> myDeepCopy</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> JSON</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">parse</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">JSON</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">stringify</span><span style=\\"color:#24292E\\">(myOriginal));</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>虽然 V8 引擎优化了 JSON 的解析速度，但是这种方式还是有一些限制条件的，如果数据中存在 Map, Date 等 JS 内置数据结构就没法正常复制。</p>\\n<h2 id=\\"手动实现-deepclone\\" tabindex=\\"-1\\">手动实现 deepClone <a class=\\"header-anchor\\" href=\\"#手动实现-deepclone\\" aria-label=\\"Permalink to &quot;手动实现 deepClone&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isObject</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">obj</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> any</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> obj </span><span style=\\"color:#D73A49\\">!==</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#D73A49\\"> &#x26;&#x26;</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> obj </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'object'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#005CC5\\"> objectToString</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> Object</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">prototype</span><span style=\\"color:#24292E\\">.toString;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> toTypeString</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">value</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#D73A49\\"> =></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  objectToString.</span><span style=\\"color:#6F42C1\\">call</span><span style=\\"color:#24292E\\">(value);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isMap</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> Map</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#005CC5\\">any</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">any</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object Map]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isSet</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> Set</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#005CC5\\">any</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object Set]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isDate</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> Date</span><span style=\\"color:#D73A49\\"> =></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object Date]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isRegExp</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#D73A49\\"> =></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object RegExp]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">T</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#6F42C1\\">isObject</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (Array.</span><span style=\\"color:#6F42C1\\">isArray</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> val.</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(deepClone) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isDate</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Date</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isMap</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Map</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isSet</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Set</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isRegExp</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(val.source, val.flags) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> Object.</span><span style=\\"color:#6F42C1\\">keys</span><span style=\\"color:#24292E\\">(val).</span><span style=\\"color:#6F42C1\\">reduce</span><span style=\\"color:#24292E\\">((</span><span style=\\"color:#E36209\\">acc</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">key</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    acc[key </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> keyof</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">(val[key </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> keyof</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> acc;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, {} </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br></div></div><p>手动实现 deepClone 可以处理 Date, Map, Set, RegExp 这些数据结构，但这也不是完美的解决方案，例如二进制的数据结构 <code>ArrayBuffer</code> 就没在处理范围，但对于绝大多数场景也足够用了。</p>\\n<h2 id=\\"使用-structuredclone\\" tabindex=\\"-1\\">使用 structuredClone <a class=\\"header-anchor\\" href=\\"#使用-structuredclone\\" aria-label=\\"Permalink to &quot;使用 structuredClone&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> myDeepCopy</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> structuredClone</span><span style=\\"color:#24292E\\">(myOriginal);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最新的浏览器标准添加了 <code>structuredClone</code> 函数，可以实现常见数据结构的复制，但是有些数据结构也是不能复制的，例如 <code>Function</code>。不过 Function 也没有复制的必要。\\n由于这个函数最近才添加，实际使用中可能还需要搭配 <a href=\\"https://github.com/zloirock/core-js#structuredclone\\" target=\\"_blank\\" rel=\\"noreferrer\\">polyfill</a>。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>实际开发工作中大家可以根据自己的需要选择合适的深拷贝解决方案。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/structuredClone\\" target=\\"_blank\\" rel=\\"noreferrer\\">structuredClone</a></p>\\n<p><a href=\\"https://web.dev/structured-clone/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Deep-copying in JavaScript using structuredClone</a></p>\\n<p><a href=\\"https://lodash.com/docs/4.17.15#cloneDeep\\" target=\\"_blank\\" rel=\\"noreferrer\\">cloneDeep</a></p>\\n"},{"title":"前端开发地图应用的调研","url":"/posts/2018-11-27-js-map/","date":"2018-11-27 21:20","tags":["js","map"],"html":"<p>我司的产品终于发布了新版本，所以忙碌的开发暂时告一段落。最近在做下一期的规划，然后就是要做前端网站来满足用户的需求。由于我们的产品是和地图强相关的，所以也对地图做了很多调研。</p>\\n<h2 id=\\"基本需求\\" tabindex=\\"-1\\">基本需求 <a class=\\"header-anchor\\" href=\\"#基本需求\\" aria-label=\\"Permalink to &quot;基本需求&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>产品需要在国内和国外使用，费用合理，可以换地图的贴图并且能在地图上绘制各种信息。例如多边形或圆形还有贝塞尔曲线。</p>\\n<h2 id=\\"mapkit-js\\" tabindex=\\"-1\\">MapKit JS <a class=\\"header-anchor\\" href=\\"#mapkit-js\\" aria-label=\\"Permalink to &quot;MapKit JS&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>苹果居然也出了网页版本的地图产品<a href=\\"https://developer.apple.com/maps/mapkitjs/\\" target=\\"_blank\\" rel=\\"noreferrer\\">MapKit JS</a>，可谓是良心。但是目前还处于 Beta 版本。如果以后要考虑产品的全平台化，显然不是一个很好的选择。不过苹果的产品可以在国内国外使用不用太担心地图偏移问题，而且可以贴图和绘制图形，但是目前网页版还不能绘制贝塞尔曲线，iOS 客户端倒是可以。</p>\\n<h2 id=\\"mapbox\\" tabindex=\\"-1\\">MapBox <a class=\\"header-anchor\\" href=\\"#mapbox\\" aria-label=\\"Permalink to &quot;MapBox&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MapBox 是一个地图服务提供商，经过调研 MapBox 使用最新的 WebGL 技术来渲染，摆脱了传统的下 tile 来贴图的方式，渲染速度得到了大大的提升。也能解决国内和国外的地图显示问题，但是画图功能就只有画线和多边形。不过提供了底层的画图层的接口，需要自己写 WebGL 的 shader。这就增加了开发成本。。。</p>\\n<h2 id=\\"googlemap\\" tabindex=\\"-1\\">GoogleMap <a class=\\"header-anchor\\" href=\\"#googlemap\\" aria-label=\\"Permalink to &quot;GoogleMap&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>谷歌地图当然好，但是我最后才说。因为谷歌无法在国内使用，这种情况下我就不得不写两套接口来对应，例如国内高德地图，国外谷歌地图，会大大增加开发成本。而且谷歌地图最近刚升级付费条款，费用是按照请求次数来收，所以用户大量增长之后的开销也会非常大。不过谷歌也不能画贝塞尔曲线。。。</p>\\n<h2 id=\\"地理坐标系\\" tabindex=\\"-1\\">地理坐标系 <a class=\\"header-anchor\\" href=\\"#地理坐标系\\" aria-label=\\"Permalink to &quot;地理坐标系&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>由于是需要在地图上绘制新的 tiles，所以自然就涉及到坐标的转换和计算。如何计算一个经纬度落在哪一张 tiles 上，以及在不同缩放级别下 tiles 的正常显示和重绘。这些都是需要自己来实现的。\\n这里有一个还算有名的官方介绍，并给出了 Python 的源码。可以参考<a href=\\"http://www.maptiler.org/google-maps-coordinates-tile-bounds-projection/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Google Maps: Coordinates, Tile Bounds and Projection</a>来进行实现。</p>\\n<h2 id=\\"坐标系转换\\" tabindex=\\"-1\\">坐标系转换 <a class=\\"header-anchor\\" href=\\"#坐标系转换\\" aria-label=\\"Permalink to &quot;坐标系转换&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>每个国家都有自己的坐标系系统，虽然 GPS 使用的<a href=\\"https://epsg.io/4326\\" target=\\"_blank\\" rel=\\"noreferrer\\">WGS 84</a>标准非常流行，但是这个是美国制定的。每个国家当然都需要根据自己国家需要来定制自己的标准。例如中国就有北京 54 坐标系，西安 80 坐标系。北京 54 和西安 80 是参心坐标系，大地原点分别在苏联和西安。难以表达高度信息，目前国家正在推广<a href=\\"https://epsg.io/4479\\" target=\\"_blank\\" rel=\\"noreferrer\\">2000 国家大地坐标系</a>,这个和 WGS84 一样是地心坐标系，即以地球质量中心为原点。日本也有自己的平面直角坐标系，我们当然需要各种坐标转换，还好有现成的开源项目<a href=\\"https://github.com/proj4js/proj4js\\" target=\\"_blank\\" rel=\\"noreferrer\\">proj4js</a>。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>各个地图服务商都各有优劣，但却没有一款完美的。主要是用途也比较特殊，可能在地图服务上进行二次开发的可能性比较高吧。不过提供地图服务的也没几家可以选择的。。。</p>\\n"}]},"relativePath":"tags/js/index.md","filePath":"tags/[slug].md"}`),l={name:"tags/js/index.md"};function p(e,o,r,t,c,y){return n(),a("div")}const b=s(l,[["render",p]]);export{u as __pageData,b as default};
